SELECT 
FROM report_event
WHERE report_id = #{reportId}
  AND sequence > #{afterSequence}
  AND epoch >= #{minEpoch}
ORDER BY sequence ASC

SELECT COALESCE(MAX(sequence), 0)
FROM report_event
WHERE job_id = #{jobId}

SELECT 
FROM report_event
WHERE report_id = #{reportId} AND event_id = #{eventId}
